/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_dp_locked` BEFORE UPDATE ON `downpayments` FOR EACH ROW BEGIN
  IF NEW.amount <> OLD.amount OR NEW.or_number <> OLD.or_number OR NEW.session_id <> OLD.session_id THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Downpayment amount, OR, and drawer are locked';
  END IF;
  IF NEW.job_id <> OLD.job_id AND NOT EXISTS (
       SELECT 1 FROM downpayment_corrections
        WHERE downpayment_id = OLD.downpayment_id AND action = 'Move' AND status = 'Approved'
          AND old_job_id = OLD.job_id AND new_job_id = NEW.job_id) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'A downpayment can only move jobs through an approved correction';
  END IF;
END */;;
DELIMITER ;
