/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_sm_check` BEFORE INSERT ON `stock_movements` FOR EACH ROW BEGIN
  DECLARE v_available DECIMAL(12,2);
  DECLARE v_allows_decimal BOOLEAN;

  SELECT allows_decimal INTO v_allows_decimal FROM items WHERE item_id = NEW.item_id;
  IF v_allows_decimal = 0 AND NEW.qty_change <> FLOOR(NEW.qty_change) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'This item only accepts whole-number quantities';
  END IF;

  IF NEW.qty_change < 0 THEN
    SELECT COALESCE(SUM(qty_change), 0) INTO v_available
      FROM stock_movements WHERE item_id = NEW.item_id;
    IF v_available + NEW.qty_change < 0 THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Not enough stock: quantity would go below zero';
    END IF;
  END IF;
END */;;
